    out.println("    System.out.println(\"This is in another java file\");");
    out.println("  }");
    out.println("}");
    out.close();
    InterpreterResult res = beam.interpret(writer.toString(), context);
    assertEquals(InterpreterResult.Code.SUCCESS, res.code());
}

