public void testEquals() {
    assertEquals(new AngularObject("name", "value", "note1", null, null), new AngularObject("name", "value", "note1", null, null));
    assertEquals(new AngularObject("name", "value", "note1", "paragraph1", null), new AngularObject("name", "value", "note1", "paragraph1", null));
