@Test
public void testRunOnSelectionChange() throws Exception {
    if (!endToEndTestEnabled()) {
        return;
    }
    try {
        String xpathToRunOnSelectionChangeCheckbox = getParagraphXPath(1) + "//ul/li/form/input[contains(@ng-checked, 'true')]";
