        waitForParagraph(2, "FINISHED");
        // check expected text
        waitForText("BindingTest_1_", By.xpath(getParagraphXPath(1) + "//div[@id=\"angularTestButton\"]"));
        driver.findElement(By.xpath(".//*[@id='main']//button[@ng-click='moveNoteToTrash(note.id)']")).sendKeys(Keys.ENTER);
