    config.put("enabled", true);
    p.setConfig(config);
    String code = "%spark.spark println(z.textbox(\"my_input\", \"default_name\"))\n" + "println(z.select(\"my_select\", \"1\"," + "Seq((\"1\", \"select_1\"), (\"2\", \"select_2\"))))\n" + "val items=z.checkbox(\"my_checkbox\", Seq(\"2\"), " + "Seq((\"1\", \"check_1\"), (\"2\", \"check_2\")))\n" + "println(items(0))";
