        public void run() {
            assertEquals(Code.SUCCESS, interpreter1.interpret("100", context1).code());
        }
    };
    long start = System.currentTimeMillis();
    thread1.start();
    thread2.start();
    thread1.join();
    thread2.join();
    long end = System.currentTimeMillis();
    assertTrue((end - start) <= 200);
}

