@Test
public void testPermissions() throws IOException {
    // create a note and a paragraph
    Note note = notebook.createNote(anonymous);
    NotebookAuthorization notebookAuthorization = notebook.getNotebookAuthorization();
    // empty owners, readers or writers means note is public
    assertEquals(notebookAuthorization.isOwner(note.getId(), new HashSet<>(Arrays.asList("user2"))), true);
    assertEquals(notebookAuthorization.isReader(note.getId(), new HashSet<>(Arrays.asList("user2"))), true);
    assertEquals(notebookAuthorization.isRunner(note.getId(), new HashSet<>(Arrays.asList("user2"))), true);
    assertEquals(notebookAuthorization.isWriter(note.getId(), new HashSet<>(Arrays.asList("user2"))), true);
    notebookAuthorization.setOwners(note.getId(), new HashSet<>(Arrays.asList("user1")));
    notebookAuthorization.setReaders(note.getId(), new HashSet<>(Arrays.asList("user1", "user2")));
    notebookAuthorization.setRunners(note.getId(), new HashSet<>(Arrays.asList("user3")));
    notebookAuthorization.setWriters(note.getId(), new HashSet<>(Arrays.asList("user1")));
    assertEquals(notebookAuthorization.isOwner(note.getId(), new HashSet<>(Arrays.asList("user2"))), false);
    assertEquals(notebookAuthorization.isOwner(note.getId(), new HashSet<>(Arrays.asList("user1"))), true);
    assertEquals(notebookAuthorization.isReader(note.getId(), new HashSet<>(Arrays.asList("user4"))), false);
    assertEquals(notebookAuthorization.isReader(note.getId(), new HashSet<>(Arrays.asList("user2"))), true);
    assertEquals(notebookAuthorization.isRunner(note.getId(), new HashSet<>(Arrays.asList("user3"))), true);
    assertEquals(notebookAuthorization.isRunner(note.getId(), new HashSet<>(Arrays.asList("user2"))), false);
    assertEquals(notebookAuthorization.isWriter(note.getId(), new HashSet<>(Arrays.asList("user2"))), false);
    assertEquals(notebookAuthorization.isWriter(note.getId(), new HashSet<>(Arrays.asList("user1"))), true);
    // Test clearing of permissions
    notebookAuthorization.setReaders(note.getId(), Sets.<String>newHashSet());
    assertEquals(notebookAuthorization.isReader(note.getId(), new HashSet<>(Arrays.asList("user2"))), true);
    assertEquals(notebookAuthorization.isReader(note.getId(), new HashSet<>(Arrays.asList("user4"))), true);
    notebook.removeNote(note.getId(), anonymous);
}

@Test
public void testAuthorizationRoles() throws IOException {
    String user1 = "user1";
    String user2 = "user2";
    Set<String> roles = Sets.newHashSet("admin");
    // set admin roles for both user1 and user2
    notebookAuthorization.setRoles(user1, roles);
    notebookAuthorization.setRoles(user2, roles);
    Note note = notebook.createNote(new AuthenticationInfo(user1));
    // check that user1 is owner, reader, runner and writer
    assertEquals(notebookAuthorization.isOwner(note.getId(), Sets.newHashSet(user1)), true);
    assertEquals(notebookAuthorization.isReader(note.getId(), Sets.newHashSet(user1)), true);
    assertEquals(notebookAuthorization.isRunner(note.getId(), Sets.newHashSet(user2)), true);
    assertEquals(notebookAuthorization.isWriter(note.getId(), Sets.newHashSet(user1)), true);
    // since user1 and user2 both have admin role, user2 will be reader and writer as well
    assertEquals(notebookAuthorization.isOwner(note.getId(), Sets.newHashSet(user2)), false);
    assertEquals(notebookAuthorization.isReader(note.getId(), Sets.newHashSet(user2)), true);
    assertEquals(notebookAuthorization.isRunner(note.getId(), Sets.newHashSet(user2)), true);
    assertEquals(notebookAuthorization.isWriter(note.getId(), Sets.newHashSet(user2)), true);
    // check that user1 has note listed in his workbench
    Set<String> user1AndRoles = notebookAuthorization.getRoles(user1);
    user1AndRoles.add(user1);
    List<Note> user1Notes = notebook.getAllNotes(user1AndRoles);
    assertEquals(user1Notes.size(), 1);
    assertEquals(user1Notes.get(0).getId(), note.getId());
    // check that user2 has note listed in his workbench because of admin role
    Set<String> user2AndRoles = notebookAuthorization.getRoles(user2);
    user2AndRoles.add(user2);
    List<Note> user2Notes = notebook.getAllNotes(user2AndRoles);
    assertEquals(user2Notes.size(), 1);
    assertEquals(user2Notes.get(0).getId(), note.getId());
}

@Test
public void testAbortParagraphStatusOnInterpreterRestart() throws InterruptedException, IOException {
    Note note = notebook.createNote(anonymous);
    interpreterSettingManager.setInterpreterBinding(anonymous.getUser(), note.getId(), interpreterSettingManager.getInterpreterSettingIds());
    // create three paragraphs
    Paragraph p1 = note.addNewParagraph(anonymous);
    p1.setText("sleep 1000");
    Paragraph p2 = note.addNewParagraph(anonymous);
    p2.setText("sleep 1000");
    Paragraph p3 = note.addNewParagraph(anonymous);
    p3.setText("sleep 1000");
    note.runAll();
    // wait until first paragraph finishes and second paragraph starts
    while (p1.getStatus() != Status.FINISHED || p2.getStatus() != Status.RUNNING) Thread.yield();
    assertEquals(Status.FINISHED, p1.getStatus());
    assertEquals(Status.RUNNING, p2.getStatus());
    assertEquals(Status.PENDING, p3.getStatus());
    // restart interpreter
    interpreterSettingManager.restart(interpreterSettingManager.getInterpreterSettings(note.getId()).get(0).getId());
    // make sure three differnt status aborted well.
    assertEquals(Status.FINISHED, p1.getStatus());
    assertEquals(Status.ABORT, p2.getStatus());
    assertEquals(Status.ABORT, p3.getStatus());
    notebook.removeNote(note.getId(), anonymous);
}

@Test
public void testPerSessionInterpreterCloseOnNoteRemoval() throws IOException {
    // create a notes
    Note note1 = notebook.createNote(anonymous);
    Paragraph p1 = note1.addNewParagraph(AuthenticationInfo.ANONYMOUS);
    p1.setText("getId");
    p1.setAuthenticationInfo(anonymous);
