        InterpreterContext context = new InterpreterContext("note", "jobId1", null, "title", "text", new AuthenticationInfo(), new HashMap<String, Object>(), new GUI(), null, new LocalResourcePool("pool1"), new LinkedList<InterpreterContextRunner>(), null);

