            return null;
        }

        @Override
        protected Object jobRun() throws Throwable {
            intpA.interpret("1000", context);
            return "1000";
        }

        @Override
        protected boolean jobAbort() {
            if (isRunning()) {
                intpA.cancel(context);
            }
            return true;
        }

        @Override
        public void setResult(Object results) {
            this.results = results;
        }
    };
    Job job2 = new Job("jobId2", "jobName2", null, 200) {

        public Object results;

        InterpreterContext context = new InterpreterContext("note", "jobId2", null, "title", "text", new AuthenticationInfo(), new HashMap<String, Object>(), new GUI(), null, new LocalResourcePool("pool1"), new LinkedList<InterpreterContextRunner>(), null);

